<template>
  <section class="git-review-page">
    <header class="git-review-page-header"><div><button type="button" class="git-back" @click="store.closeGitReview()">{{ store.projectExplorer ? '← 返回项目' : '← 返回对话' }}</button><h1>{{ projectName }}</h1><p>{{ snapshot?.branch || 'Git 审阅' }}</p></div><div class="git-review-network"><button type="button" :disabled="busy" @click="network('fetch')">Fetch</button><button type="button" :disabled="busy" @click="network('pull')">Pull</button><button type="button" :disabled="busy" @click="network('push')">Push</button></div></header>
    <p v-if="error" class="git-review-error">{{ error }}</p>
    <template v-if="snapshot">
      <nav class="git-review-tabs"><button :class="{ on: tab === 'diff' }" @click="tab = 'diff'">变更审阅</button><button :class="{ on: tab === 'commit' }" @click="tab = 'commit'">提交 <span>{{ snapshot.staged.length }}</span></button><button :class="{ on: tab === 'history' }" @click="tab = 'history'">历史</button></nav>
      <section v-if="tab === 'diff'" class="git-review-layout"><aside class="git-review-files"><details v-for="group in fileGroups" :key="group.folder" open><summary><span>⌄</span>{{ group.folder }} <small>{{ group.files.length }}</small></summary><button v-for="file in group.files" :key="`${file.staged}:${file.path}`" type="button" :class="{ selected: selected?.path === file.path && selected.staged === file.staged }" @click="selectFile(file.path, file.staged)"><b>{{ file.status === '未跟踪' ? '?' : file.status }}</b><span :title="file.path">{{ fileName(file.path) }}</span><small>{{ file.staged ? '已暂存' : '变更' }}</small></button></details><p v-if="!allFiles.length">工作区干净。</p></aside><div class="git-review-diff"><header><div><small>Diff</small><strong>{{ selected?.path || '选择文件查看 Diff' }}</strong></div><div v-if="selected"><button type="button" @click="selected.staged ? unstage(selected.path) : stage(selected.path)">{{ selected.staged ? '取消暂存' : '暂存' }}</button><button type="button" class="danger" @click="restore">还原</button></div></header><pre v-if="!selected">选择一个文件后，将在这里显示完整对比。</pre><pre v-else-if="diff === null">正在读取完整 Diff…</pre><pre v-else-if="diff">{{ diff }}</pre><pre v-else>该文件当前没有可比较的文本差异；请刷新状态后重试。</pre></div></section>
      <section v-else-if="tab === 'commit'" class="git-commit-page"><div class="git-commit-summary"><strong>已暂存 {{ snapshot.staged.length }} 个文件</strong><p>只有已暂存的变更会被提交。</p><button v-for="file in snapshot.staged" :key="file.path" type="button" @click="selectFile(file.path, true); tab = 'diff'">{{ file.status }} {{ file.path }}</button></div><form @submit.prevent="commit"><label>提交说明<textarea v-model="message" rows="4" placeholder="简洁说明这次修改的目的" autofocus /></label><section v-if="identityOpen" class="git-review-identity"><input v-model="userName" placeholder="Git 名称" /><input v-model="userEmail" placeholder="Git 邮箱" /><button type="button" @click="configure">保存身份</button></section><button type="submit" class="button-primary" :disabled="!snapshot.staged.length || !message.trim()">提交更改</button></form></section>
      <section v-else class="git-history-page"><header><h2>提交历史</h2><p>回滚会执行 <code>git reset --hard</code>，丢弃目标提交之后的工作区和暂存区改动。</p></header><article v-for="item in snapshot.history" :key="item.id"><div><strong>{{ item.subject }}</strong><small>{{ item.author }} · {{ item.date }} · {{ item.id.slice(0, 8) }}</small></div><button type="button" class="danger" @click="reset(item.id)">回滚到此提交</button></article><p v-if="!snapshot.history.length">还没有提交记录。</p></section>
    </template>
    <div v-else class="git-review-loading">正在读取 Git 信息…</div>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import { gitCommit, gitConfigure, gitDiff, gitFetch, gitPull, gitPush, gitResetHard, gitRestoreFile, gitSnapshot, gitStage } from "../lib/ipc";
import type { GitSnapshot } from "../lib/types";
import { useSessionStore } from "../stores/session";
const store = useSessionStore();
const snapshot = ref<GitSnapshot | null>(null), error = ref(""), busy = ref(false), message = ref(""), identityOpen = ref(false);
const tab = ref<"diff" | "commit" | "history">("diff"); const selected = ref<{ path: string; staged: boolean } | null>(null); const diff = ref<string | null>(null); const userName = ref(""), userEmail = ref("");
const root = computed(() => store.gitReview?.root ?? ""); const projectName = computed(() => root.value.split(/[\\/]/).filter(Boolean).pop() || "Git");
const allFiles = computed(() => snapshot.value ? [...snapshot.value.staged.map((file) => ({ ...file, staged: true })), ...snapshot.value.unstaged.map((file) => ({ ...file, staged: false })), ...snapshot.value.untracked.map((file) => ({ ...file, staged: false }))] : []);
const fileGroups = computed(() => { const groups = new Map<string, typeof allFiles.value>(); for (const file of allFiles.value) { const parts = file.path.split("/"); const folder = parts.length > 1 ? parts.slice(0, -1).join("/") : "根目录"; groups.set(folder, [...(groups.get(folder) ?? []), file]); } return [...groups].map(([folder, files]) => ({ folder, files })); });
function fileName(path: string) { return path.split("/").pop() || path; }
async function refresh() { if (!root.value) return; error.value = ""; try { snapshot.value = await gitSnapshot(root.value); userName.value = snapshot.value.userName; userEmail.value = snapshot.value.userEmail; } catch (err) { error.value = String(err); } }
async function selectFile(path: string, staged: boolean) { if (!root.value) return; selected.value = { path, staged }; diff.value = null; diff.value = await gitDiff(root.value, path, staged).catch((err) => `无法读取 Diff：${String(err)}`); }
async function stage(path: string) { if (!root.value) return; snapshot.value = await gitStage(root.value, path); await selectFile(path, true); notify(); }
async function unstage(path: string) { if (!root.value) return; snapshot.value = await gitStage(root.value, path, true); await selectFile(path, false); notify(); }
async function restore() { if (!root.value || !selected.value || !window.confirm(`还原 ${selected.value.path} 的未提交改动？`)) return; snapshot.value = await gitRestoreFile(root.value, selected.value.path, selected.value.staged); selected.value = null; diff.value = null; notify(); }
async function configure() { if (!root.value || !userName.value.trim() || !userEmail.value.trim()) return; snapshot.value = await gitConfigure(root.value, userName.value.trim(), userEmail.value.trim()); identityOpen.value = false; }
async function commit() { if (!root.value || !message.value.trim()) return; if (!snapshot.value?.userName || !snapshot.value?.userEmail) { identityOpen.value = true; return; } try { snapshot.value = await gitCommit(root.value, message.value.trim()); message.value = ""; tab.value = "history"; notify(); } catch (err) { error.value = String(err); } }
async function reset(id: string) { if (!root.value || !window.confirm(`确认回滚到 ${id.slice(0, 8)}？这会丢弃之后所有未提交和已提交改动。`)) return; try { snapshot.value = await gitResetHard(root.value, id); notify(); } catch (err) { error.value = String(err); } }
async function network(action: "fetch" | "pull" | "push") { if (!root.value) return; busy.value = true; error.value = ""; try { snapshot.value = await ({ fetch: gitFetch, pull: gitPull, push: gitPush }[action])(root.value); notify(); } catch (err) { error.value = String(err); } finally { busy.value = false; } }
function notify() { window.dispatchEvent(new Event("dandelion:git-refresh")); }
watch(() => store.gitReview, (target) => { if (!target) return; tab.value = target.view; selected.value = target.path ? { path: target.path, staged: !!target.staged } : null; void refresh().then(() => { if (target.path) return selectFile(target.path, !!target.staged); }); }, { deep: true });
onMounted(() => { const target = store.gitReview; if (target) { tab.value = target.view; selected.value = target.path ? { path: target.path, staged: !!target.staged } : null; void refresh().then(() => { if (target.path) return selectFile(target.path, !!target.staged); }); } });
</script>
